<?php if ( ! defined( 'ABSPATH' ) ) { exit; } get_header(); ?>
<main id="content" class="avela-shell avela-page"><header class="avela-page-head"><p class="avela-eyebrow"><?php esc_html_e( 'The journal', 'avela' ); ?></p><h1><?php if ( is_search() ) { printf( esc_html__( 'Search results for: %s', 'avela' ), esc_html( get_search_query() ) ); } elseif ( is_archive() ) { the_archive_title(); } else { esc_html_e( 'Notes & inspiration', 'avela' ); } ?></h1><?php if ( is_archive() ) { the_archive_description(); } ?></header>
<?php if ( have_posts() ) : ?><div class="avela-post-grid"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class( 'avela-post-card' ); ?>><?php if ( has_post_thumbnail() ) : ?><a href="<?php the_permalink(); ?>"><?php the_post_thumbnail( 'medium_large' ); ?></a><?php endif; ?><p class="avela-eyebrow"><?php echo esc_html( get_the_date() ); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php endwhile; ?></div><?php the_posts_pagination(); else : ?><p><?php esc_html_e( 'Nothing found. Try another search.', 'avela' ); ?></p><?php get_search_form(); endif; ?></main><?php get_footer(); ?>
